SELECT cust_num AS custNum, cell_md5 AS cell FROM ( SELECT cust_num, cell_md5, ROW_NUMBER() OVER (PARTITION BY cust_num ORDER BY create_time DESC) AS rn FROM b_marketing_sync_${apiCode} WHERE status = 1 AND cust_num IN
#{userKey}
) t WHERE rn = 1
